/**
 * Current Codex authors WorldPlan and TownPatch; this CLI only validates, dispatches contracts and merges.
 * No hidden LLM/API keys, runtime map writes, or geometry generated by an LLM.
 */
import fs from 'node:fs/promises';
import path from 'node:path';
import { createTownTasks, mergeTownPatch, validateWorldBundle, validateWorldPlan, type WorldBundle } from '../src/shared/worldPlanning';

const [command, input, ...args] = process.argv.slice(2);
const read = async (file: string) => JSON.parse((await fs.readFile(file,'utf8')).replace(/^\uFEFF/,''));
const write = async (file: string, value: unknown) => {
  await fs.mkdir(path.dirname(file),{recursive:true});
  await fs.writeFile(file,JSON.stringify(value,null,2)+'\n');
};
try {
  if (!input) throw new Error('Usage: node --import tsx scripts/worldPlanner.ts tasks <plan.json> <output-dir> | merge <plan-or-bundle.json> <patch.json>... --out <bundle.json> | validate <plan-or-bundle.json>');
  const raw = await read(input);
  if (command==='tasks') {
    if(args.length!==1) throw new Error('tasks needs one output directory');
    const plan=validateWorldPlan(raw.plan ?? raw);
    const tasks=createTownTasks(plan);
    // Complete validation precedes any artifact writes.
    await fs.mkdir(args[0],{recursive:true});
    for (const [index,task] of tasks.entries()) await write(path.join(args[0],String(index).padStart(2,'0')+'-'+task.town.id+'.json'),task);
    await write(path.join(args[0],'world-plan.json'),plan);
    console.log(JSON.stringify({tasks:tasks.map(t=>t.town.id),output:path.resolve(args[0])}));
  } else if(command==='merge') {
    const outIndex=args.indexOf('--out');
    if(outIndex<1||outIndex!==args.length-2) throw new Error('merge needs patches followed by --out <bundle.json>');
    let bundle: WorldBundle=raw.plan?validateWorldBundle(raw):{plan:validateWorldPlan(raw),patches:[]};
    for(const filename of args.slice(0,outIndex)) bundle=mergeTownPatch(bundle,await read(filename));
    await write(args[outIndex+1],bundle);
    console.log(JSON.stringify({towns:bundle.patches.map(p=>p.townId),output:path.resolve(args[outIndex+1])}));
  } else if(command==='validate') {
    const bundle: WorldBundle=raw.plan?validateWorldBundle(raw):{plan:validateWorldPlan(raw),patches:[]};
    console.log(JSON.stringify({valid:true,world:bundle.plan.id,revision:bundle.plan.revision,towns:bundle.plan.towns.length,
      completed:bundle.patches.length,buildings:bundle.patches.reduce((n,p)=>n+p.buildings.length,0),roads:bundle.plan.roads.length}));
  } else throw new Error('Unknown command: '+command);
} catch(error) {
  console.error(error instanceof Error?error.message:String(error));
  process.exitCode=1;
}

